from models import Product, Location, StockLevel, Movement
from storage import JsonStore


class InsufficientStock(Exception):
    pass


class CapacityExceeded(Exception):
    pass


class DuplicateRef(Exception):
    pass


class Inventory:
    def __init__(self, store: JsonStore):
        self.store = store

    # --- helpers -----------------------------------------------------------
    def _check_ref(self, ref: str) -> None:
        for m in self.store.load()["movements"]:
            if m.ref == ref:
                raise DuplicateRef(f"ref already used: {ref}")

    def _qty_ok(self, qty: int) -> None:
        if qty <= 0:
            raise ValueError("qty must be > 0")

    def _on_hand_at(self, sku: str, code: str) -> int:
        return self.store.stock_at(sku, code)

    def _used_capacity(self, code: str) -> int:
        total = 0
        for s in self.store.load()["stock"]:
            if s.location_code == code:
                total += s.quantity
        return total

    # --- operations --------------------------------------------------------
    def receive(self, sku: str, qty: int, dst: str, ref: str) -> Movement:
        self._qty_ok(qty)
        self._check_ref(ref)
        product = self.store.get_product(sku)
        loc = self.store.get_location(dst)
        if self._used_capacity(dst) + qty > loc.capacity:
            raise CapacityExceeded(f"location {dst} over capacity")
        self.store.set_stock(sku, dst, self._on_hand_at(sku, dst) + qty)
        m = Movement("receive", sku, qty, None, dst, self._ts(), ref)
        self.store.append_movement(m)
        return m

    def ship(self, sku: str, qty: int, src: str, ref: str) -> Movement:
        self._qty_ok(qty)
        self._check_ref(ref)
        self.store.get_product(sku)
        self.store.get_location(src)
        if self._on_hand_at(sku, src) < qty:
            raise InsufficientStock(f"not enough {sku} at {src}")
        self.store.set_stock(sku, src, self._on_hand_at(sku, src) - qty)
        m = Movement("ship", sku, qty, src, None, self._ts(), ref)
        self.store.append_movement(m)
        return m

    def transfer(self, sku: str, qty: int, src: str, dst: str, ref: str) -> Movement:
        self._qty_ok(qty)
        self._check_ref(ref)
        self.store.get_product(sku)
        self.store.get_location(src)
        self.store.get_location(dst)
        if self._on_hand_at(sku, src) < qty:
            raise InsufficientStock(f"not enough {sku} at {src}")
        if self._used_capacity(dst) + qty > self.store.get_location(dst).capacity:
            raise CapacityExceeded(f"location {dst} over capacity")
        self.store.set_stock(sku, src, self._on_hand_at(sku, src) - qty)
        self.store.set_stock(sku, dst, self._on_hand_at(sku, dst) + qty)
        m = Movement("transfer", sku, qty, src, dst, self._ts(), ref)
        self.store.append_movement(m)
        return m

    def adjust(self, sku: str, qty_delta: int, loc: str, ref: str) -> Movement:
        self._check_ref(ref)
        if qty_delta == 0:
            raise ValueError("qty_delta must be non-zero")
        self.store.get_product(sku)
        self.store.get_location(loc)
        new_qty = self._on_hand_at(sku, loc) + qty_delta
        if new_qty < 0:
            raise InsufficientStock(f"adjust would make {sku} negative at {loc}")
        if qty_delta > 0 and self._used_capacity(loc) + qty_delta > self.store.get_location(loc).capacity:
            raise CapacityExceeded(f"location {loc} over capacity")
        self.store.set_stock(sku, loc, new_qty)
        m = Movement("adjust", sku, qty_delta, loc, None, self._ts(), ref)
        self.store.append_movement(m)
        return m

    def _ts(self) -> int:
        movements = self.store.load()["movements"]
        if movements:
            return max(m.ts for m in movements) + 1
        return 0

    # --- reports -----------------------------------------------------------
    def total_on_hand(self, sku: str) -> int:
        self.store.get_product(sku)
        return sum(s.quantity for s in self.store.load()["stock"] if s.sku == sku)

    def below_reorder(self) -> list:
        out = []
        for p in self.store.load()["products"]:
            total = sum(s.quantity for s in self.store.load()["stock"] if s.sku == p.sku)
            if total < p.reorder_point:
                out.append(p.sku)
        return out

    def valuation(self) -> float:
        total = 0.0
        products = {p.sku: p for p in self.store.load()["products"]}
        for s in self.store.load()["stock"]:
            total += s.quantity * products[s.sku].unit_cost
        return total

    def ledger(self, sku: str) -> list:
        self.store.get_product(sku)
        moves = [m for m in self.store.load()["movements"] if m.sku == sku]
        moves.sort(key=lambda m: m.ts)
        return moves
