import json
import os
import tempfile

from models import Product, Location, StockLevel, Movement

_EMPTY = {"products": [], "locations": [], "stock": [], "movements": []}


class JsonStore:
    def __init__(self, path: str):
        self.path = path
        if not os.path.exists(path):
            self._write(_EMPTY)

    # -- raw disk I/O -------------------------------------------------------
    def _read_raw(self) -> dict:
        with open(self.path, "r", encoding="utf-8") as f:
            return json.load(f)

    def _write(self, obj: dict) -> None:
        directory = os.path.dirname(os.path.abspath(self.path)) or "."
        fd, tmp = tempfile.mkstemp(dir=directory, suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(obj, f)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, self.path)
        except BaseException:
            if os.path.exists(tmp):
                os.remove(tmp)
            raise

    # -- typed load/save ----------------------------------------------------
    def load(self) -> dict:
        raw = self._read_raw()
        return {
            "products": [Product.from_dict(d) for d in raw["products"]],
            "locations": [Location.from_dict(d) for d in raw["locations"]],
            "stock": [StockLevel.from_dict(d) for d in raw["stock"]],
            "movements": [Movement.from_dict(d) for d in raw["movements"]],
        }

    def save(self, data: dict) -> None:
        self._write({
            "products": [p.to_dict() for p in data["products"]],
            "locations": [l.to_dict() for l in data["locations"]],
            "stock": [s.to_dict() for s in data["stock"]],
            "movements": [m.to_dict() for m in data["movements"]],
        })

    # -- lookups / mutations -------------------------------------------------
    def get_product(self, sku: str) -> Product:
        for d in self._read_raw()["products"]:
            if d["sku"] == sku:
                return Product.from_dict(d)
        raise KeyError(sku)

    def get_location(self, code: str) -> Location:
        for d in self._read_raw()["locations"]:
            if d["code"] == code:
                return Location.from_dict(d)
        raise KeyError(code)

    def stock_at(self, sku: str, code: str) -> int:
        self.get_product(sku)
        self.get_location(code)
        for d in self._read_raw()["stock"]:
            if d["sku"] == sku and d["location_code"] == code:
                return d["quantity"]
        return 0

    def set_stock(self, sku: str, code: str, qty: int) -> None:
        self.get_product(sku)
        self.get_location(code)
        data = self._read_raw()
        for d in data["stock"]:
            if d["sku"] == sku and d["location_code"] == code:
                d["quantity"] = qty
                self._write(data)
                return
        data["stock"].append(StockLevel(sku, code, qty).to_dict())
        self._write(data)

    def append_movement(self, m: Movement) -> None:
        data = self._read_raw()
        data["movements"].append(m.to_dict())
        self._write(data)
