```python
from models import Movement
from storage import JsonStore


class InsufficientStock(Exception):
    pass


class CapacityExceeded(Exception):
    pass


class DuplicateRef(Exception):
    pass


class Inventory:
    def __init__(self, store: JsonStore):
        self.store = store

    # -- guards ---------------------------------------------------------------
    def _check_qty_positive(self, qty: int) -> None:
        if qty <= 0:
            raise ValueError("qty must be > 0")

    def _check_ref_unique(self, ref: str) -> None:
        for m in self.store.load()["movements"]:
            if m.ref == ref:
                raise DuplicateRef(f"ref already used: {ref!r}")

    def _used_capacity(self, code: str) -> int:
        # capacity is consumed by ALL skus stored at this location
        return sum(
            s.quantity
            for s in self.store.load()["stock"]
            if s.location_code == code
        )

    def _check_capacity(self, code: str, incoming: int) -> None:
        loc = self.store.get_location(code)
        if self._used_capacity(code) + incoming > loc.capacity:
            raise CapacityExceeded(
                f"location {code!r} over capacity "
                f"({self._used_capacity(code)} used + {incoming} > {loc.capacity})"
            )

    def _next_ts(self) -> int:
        movements = self.store.load()["movements"]
        return (max(m.ts for m in movements) + 1) if movements else 0

    # -- operations ------------------------------------------------------------
    def receive(self, sku: str, qty: int, dst: str, ref: str) -> Movement:
        self._check_qty_positive(qty)
        self._check_ref_unique(ref)
        self.store.get_product(sku)
        self.store.get_location(dst)
        self._check_capacity(dst, qty)
        self.store.set_stock(sku, dst, self.store.stock_at(sku, dst) + qty)
        m = Movement("receive", sku, qty, None, dst, self._next_ts(), ref)
        self.store.append_movement(m)
        return m

    def ship(self, sku: str, qty: int, src: str, ref: str) -> Movement:
        self._check_qty_positive(qty)
        self._check_ref_unique(ref)
        self.store.get_product(sku)
        self.store.get_location(src)
        on_hand = self.store.stock_at(sku, src)
        if on_hand < qty:
            raise InsufficientStock(
                f"{sku!r} at {src!r}: have {on_hand}, need {qty}"
            )
        self.store.set_stock(sku, src, on_hand - qty)
        m = Movement("ship", sku, qty, src, None, self._next_ts(), ref)
        self.store.append_movement(m)
        return m

    def transfer(self, sku: str, qty: int, src: str, dst: str, ref: str) -> Movement:
        self._check_qty_positive(qty)
        self._check_ref_unique(ref)
        self.store.get_product(sku)
        self.store.get_location(src)
        self.store.get_location(dst)
        on_hand = self.store.stock_at(sku, src)
        if on_hand < qty:
            raise InsufficientStock(
                f"{sku!r} at {src!r}: have {on_hand}, need {qty}"
            )
        # capacity at dst ignores what is leaving src (unless src == dst)
        incoming = qty if src != dst else 0
        self._check_capacity(dst, incoming)
        self.store.set_stock(sku, src, on_hand - qty)
        self.store.set_stock(sku, dst, self.store.stock_at(sku, dst) + qty)
        m = Movement("transfer", sku, qty, src, dst, self._next_ts(), ref)
        self.store.append_movement(m)
        return m

    def adjust(self, sku: str, qty_delta: int, loc: str, ref: str) -> Movement:
        # adjust takes a delta (may be negative); only guard is no negative stock
        self._check_ref_unique(ref)
        self.store.get_product(sku)
        self.store.get_location(loc)
        new_qty = self.store.stock_at(sku, loc) + qty_delta
        if new_qty < 0:
            raise InsufficientStock(
                f"adjust would make {sku!r} negative at {loc!r}"
            )
        if qty_delta > 0:
            self._check_capacity(loc, qty_delta)
        self.store.set_stock(sku, loc, new_qty)
        m = Movement("adjust", sku, qty_delta, loc, None, self._next_ts(), ref)
        self.store.append_movement(m)
        return m

    # -- reports -----------------------------------------------------------------
    def total_on_hand(self, sku: str) -> int:
        self.store.get_product(sku)
        return sum(
            s.quantity for s in self.store.load()["stock"] if s.sku == sku
        )

    def below_reorder(self) -> list:
        out = []
        for p in self.store.load()["products"]:
            if self.total_on_hand(p.sku) < p.reorder_point:
                out.append(p.sku)
        return out

    def valuation(self) -> float:
        products = {p.sku: p for p in self.store.load()["products"]}
        return float(sum(
            s.quantity * products[s.sku].unit_cost
            for s in self.store.load()["stock"]
        ))

    def ledger(self, sku: str) -> list:
        self.store.get_product(sku)
        moves = [m for m in self.store.load()["movements"] if m.sku == sku]
        moves.sort(key=lambda m: m.ts)
        return moves
