import argparse
import json
import sys

from rules import Inventory
from storage import JsonStore


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="warehouse")
    p.add_argument("--db", required=True, help="path to the JSON store file")
    sub = p.add_subparsers(dest="cmd", required=True)

    def simple(name, help_text):
        sp = sub.add_parser(name, help=help_text)
        sp.add_argument("sku")
        sp.add_argument("qty", type=int)
        sp.add_argument("loc")
        sp.add_argument("ref")
        return sp

    simple("receive", "receive qty of sku into loc")
    simple("ship", "ship qty of sku from loc")
    sp = sub.add_parser("transfer", help="move qty of sku src -> dst")
    sp.add_argument("sku")
    sp.add_argument("qty", type=int)
    sp.add_argument("src")
    sp.add_argument("dst")
    sp.add_argument("ref")
    sp = sub.add_parser("adjust", help="apply signed delta to sku at loc")
    sp.add_argument("sku")
    sp.add_argument("qty_delta", type=int)
    sp.add_argument("loc")
    sp.add_argument("ref")
    sub.add_parser("report", help="valuation / below_reorder / total_units")
    return p


def main(argv=None) -> int:
    args = build_parser().parse_args(argv)
    inv = Inventory(JsonStore(args.db))
    try:
        if args.cmd == "receive":
            m = inv.receive(args.sku, args.qty, args.loc, args.ref)
            out = {"ok": True, "movement": m.to_dict()}
        elif args.cmd == "ship":
            m = inv.ship(args.sku, args.qty, args.loc, args.ref)
            out = {"ok": True, "movement": m.to_dict()}
        elif args.cmd == "transfer":
            m = inv.transfer(args.sku, args.qty, args.src, args.dst, args.ref)
            out = {"ok": True, "movement": m.to_dict()}
        elif args.cmd == "adjust":
            m = inv.adjust(args.sku, args.qty_delta, args.loc, args.ref)
            out = {"ok": True, "movement": m.to_dict()}
        elif args.cmd == "report":
            out = {
                "ok": True,
                "valuation": inv.valuation(),
                "below_reorder": inv.below_reorder(),
                "total_units": sum(
                    s.quantity for s in inv.store.load()["stock"]
                ),
            }
        else:  # pragma: no cover - argparse rejects anything else
            raise ValueError(f"unknown command: {args.cmd}")
    except Exception as e:
        print(json.dumps({
            "ok": False,
            "error": str(e).strip("'\""),
            "type": type(e).__name__,
        }))
        return 1
    print(json.dumps(out))
    return 0


if __name__ == "__main__":
    sys.exit(main())
